insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_63_v1'
from (values
('127.407.d.1.A',3,'A team designing a rain garden to filter runoff first writes down what the garden must do. This stage of the engineering design process is:','["defining the problem", "testing the prototype", "presenting results", "manufacturing"]'::jsonb,0,'Design begins by defining the need.','original'),
('127.407.d.1.A',4,'After a pilot filter clogs in testing, the team changes the design and tests again. This repeated cycle is called:','["termination", "iteration", "litigation", "isolation"]'::jsonb,1,'Iteration refines a design.','original'),
('127.407.d.1.B',3,'A town wants one project to cover stormwater, drinking water, and wastewater. Compared with a single-system project, its complexity is:','["unchanged", "zero", "greater", "smaller"]'::jsonb,2,'More systems add complexity.','original'),
('127.407.d.1.B',4,'A water project has funding for 10 workers but needs 25. This is a limit on its:','["ethics code", "scope statement", "logo", "resources"]'::jsonb,3,'Staff and money are resources.','original'),
('127.407.d.1.C',3,'Residents near a proposed treatment plant, the city council, and the state regulator all affect the design as:','["stakeholders", "suppliers only", "inspectors only", "competitors"]'::jsonb,0,'Stakeholders have an interest in the outcome.','original'),
('127.407.d.1.C',4,'A neighborhood group objects to the smell from a planned plant, so engineers add odor control. The group influenced the design as a:','["auditor", "stakeholder", "subcontractor", "supplier"]'::jsonb,1,'Stakeholder concerns shape requirements.','original'),
('127.407.d.1.D',3,'A model levee fails during a flood test. For engineers, this failure is most useful as:','["a reason to hide results", "proof engineering is useless", "data for improving the design", "a final grade"]'::jsonb,2,'Failures reveal weaknesses.','original'),
('127.407.d.1.D',4,'Engineers study why a dam spillway cracked so that future spillways avoid the same weakness. This practice treats failure as:','["a sign to quit", "an accident to ignore", "a secret", "a source of learning"]'::jsonb,3,'Failure analysis drives improvement.','original'),
('127.407.d.2.A',3,'Handing the finished wetland restoration to the owner and archiving the records belongs to which project phase?','["closing", "executing", "planning", "initiating"]'::jsonb,0,'Closing ends the project formally.','original'),
('127.407.d.2.A',4,'Comparing wetland construction progress to the schedule each week is part of which project phase?','["initiating", "monitoring and controlling", "planning only", "closing"]'::jsonb,1,'Monitoring tracks actual versus planned work.','original'),
('127.407.d.2.B',3,'On a water-treatment project, the person who coordinates schedule, budget, and team tasks is the:','["customer", "intern", "project manager", "inspector"]'::jsonb,2,'Managers coordinate the work.','original'),
('127.407.d.2.B',4,'On a design team, the member who writes meeting notes and tracks action items is the:','["sponsor", "auditor", "judge", "recorder"]'::jsonb,3,'Teams assign a recorder role.','original'),
('127.407.d.2.C',3,'A Gantt chart helps a project team see:','["task start and end dates", "tax rates", "employee ages", "water quality only"]'::jsonb,0,'Gantt charts show the schedule.','original'),
('127.407.d.2.C',4,'A task board with To Do, Doing, and Done columns is an example of a:','["land survey", "visual management tool", "tax form", "water test"]'::jsonb,1,'Boards show workflow status.','original'),
('127.407.d.2.D',3,'Putting current drawings in one shared folder with version numbers helps a team avoid:','["meeting deadlines", "hiring staff", "using outdated plans", "saving money"]'::jsonb,2,'Version control prevents errors.','original'),
('127.407.d.2.D',4,'A document log records who changed a specification and when. This supports:','["avoiding review", "wasting time", "hiding mistakes", "tracking changes"]'::jsonb,3,'Logs keep a history of changes.','original'),
('127.407.d.2.E',3,'A permit rule says effluent must stay under a set pollutant limit. For the design team, this is a:','["requirement", "holiday", "hobby", "rumor"]'::jsonb,0,'Permit limits are design requirements.','original'),
('127.407.d.2.E',4,'A final report, a working filter, and a maintenance guide due at project end are examples of:','["constraints", "deliverables", "stakeholders", "risks"]'::jsonb,1,'Deliverables are the products of a project.','original'),
('127.407.d.2.F',3,'A treatment project spends $40,000 on materials, $15,000 on equipment, and $25,000 on labor. The total cost is:','["$95,000", "$65,000", "$80,000", "$55,000"]'::jsonb,2,'40,000 + 15,000 + 25,000 = 80,000.','original'),
('127.407.d.2.F',4,'A project budget is $120,000 and $87,000 has been spent. How much remains?','["$207,000", "$43,000", "$23,000", "$33,000"]'::jsonb,3,'120,000 - 87,000 = 33,000.','original'),
('127.407.d.2.G',3,'Swapping a chlorine feed pump for a different model without review could cause new hazards. Management of change requires the swap to be:','["reviewed and approved first", "delayed forever", "made quietly", "made by anyone"]'::jsonb,0,'MOC reviews effects before changes.','original'),
('127.407.d.2.G',4,'A management of change review in a water plant mainly aims to keep a modification from creating:','["extra holidays", "unexpected safety or environmental risks", "new advertising", "bigger paychecks"]'::jsonb,1,'MOC protects people and the environment.','original'),
('127.407.d.3.A',3,'The Texas Engineering Practices Act regulates who may offer:','["restaurant meals", "legal advice", "engineering services to the public", "medical care"]'::jsonb,2,'The Act licenses engineering practice.','original'),
('127.407.d.3.A',4,'Under Texas law, a person who signs and seals engineering plans for the public must be a:','["salesperson", "school volunteer", "apprentice only", "licensed professional engineer"]'::jsonb,3,'Licensure protects the public.','original'),
('127.407.d.3.B',3,'The 1937 New London school explosion in Texas was caused by an undetected buildup of:','["natural gas", "steam", "smoke", "chalk dust"]'::jsonb,0,'Odorless leaking gas ignited.','original'),
('127.407.d.3.B',4,'After the New London explosion, Texas required that natural gas be given an added:','["sweetener", "odorant", "flavor", "color dye"]'::jsonb,1,'A smell lets people detect leaks.','original'),
('127.407.d.3.C',3,'A factory could save money by dumping untreated waste into a creek, but that would harm the ecosystem. An engineer''s ethics code puts public welfare and the environment:','["last", "after profit", "first", "never"]'::jsonb,2,'Ethics codes put public welfare first.','original'),
('127.407.d.3.C',4,'An engineer finds that the cheapest plant design will raise river temperatures and harm fish. The best response is to:','["blame the fish", "choose cost alone", "hide the finding", "propose a design that protects the river"]'::jsonb,3,'Engineers weigh environmental harm honestly.','original'),
('127.407.d.3.D',3,'A dam gives electricity and flood control but changes fish habitat. This shows that solutions can have:','["both benefits and harms", "only benefits", "no effects", "only harms"]'::jsonb,0,'Solutions have mixed impacts.','original'),
('127.407.d.3.D',4,'Burning trash to cut landfill volume can solve one problem while adding:','["more water", "air emissions", "free land", "less cost always"]'::jsonb,1,'A fix can create a new impact.','original'),
('127.407.d.4.A',3,'To make a physical model of a river system, a team first needs to:','["paint the model", "ship the model", "identify the key parts to represent", "sell the model"]'::jsonb,2,'Models start with deciding what matters.','original'),
('127.407.d.4.A',4,'Writing the sequence of building steps for a small watershed model before starting helps the team to:','["hide mistakes", "avoid planning", "skip testing", "avoid errors and wasted materials"]'::jsonb,3,'Planned steps save materials.','original'),
('127.407.d.4.B',3,'A tabletop model of a bay cannot show every real-world factor, which is a:','["limitation of models", "proof of failure", "unit of measure", "law of nature"]'::jsonb,0,'Models simplify reality.','original'),
('127.407.d.4.B',4,'A 1:100 scale model of a channel is useful mainly because it is:','["immune to error", "smaller and cheaper to test", "larger than the original", "exactly the real thing"]'::jsonb,1,'Scale models reduce cost and size.','original'),
('127.407.d.4.C',3,'A student builds a landfill cross-section model using clear plastic, soil, and gravel. Choosing these items is picking appropriate:','["careers", "laws", "materials", "units"]'::jsonb,2,'Materials are chosen to fit the model.','original'),
('127.407.d.4.C',4,'A scale ruler is the best tool for checking that a model''s parts match the:','["price list", "weather forecast", "time zone", "drawing''s dimensions"]'::jsonb,3,'Scale rulers read drawing dimensions.','original'),
('127.407.d.4.D',3,'A model of a wastewater plant should show the order of treatment steps so it accurately represents the:','["key stages of the process", "parking layout", "owner''s name", "color of the building"]'::jsonb,0,'Good models capture the key aspects.','original'),
('127.407.d.4.D',4,'A model that leaves out the main flow path of a system would be:','["finished", "inaccurate", "unnecessary", "perfect"]'::jsonb,1,'Missing key parts makes a model misleading.','original'),
('127.407.d.4.E',3,'A design proposal for a water filter may combine sketches, a computer drawing, and a:','["coupon", "rumor", "physical mockup", "password"]'::jsonb,2,'Proposals use several media.','original'),
('127.407.d.4.E',4,'Using several media in a design proposal helps the audience to:','["skip the details", "ignore costs", "avoid questions", "understand the concept in more than one way"]'::jsonb,3,'Varied media clarify ideas.','original'),
('127.407.d.4.F',3,'After testing a model oil-spill barrier, a team lists what worked and what leaked. This is:','["evaluating the model", "naming the model", "buying the model", "cleaning the model"]'::jsonb,0,'Evaluation weighs successes and failures.','original'),
('127.407.d.4.F',4,'A failed leak test on a model gives the team information for the next:','["holiday", "design iteration", "election", "invoice"]'::jsonb,1,'Failures guide the next version.','original'),
('127.407.d.5.A',3,'Before designing a fix for a polluted pond, engineers gather water tests and land-use maps. This step is:','["selling a product", "picking a color", "collecting relevant data", "closing the project"]'::jsonb,2,'Problem solving starts with information.','original'),
('127.407.d.5.A',4,'An engineer reads a table of nitrate readings and concludes that levels rise after heavy rain. This is:','["guessing", "destroying data", "advertising", "interpreting data"]'::jsonb,3,'Interpretation finds meaning in data.','original'),
('127.407.d.5.B',3,'An engineer records each design decision with the date and the reason for it. This follows best practices for:','["documenting the design process", "storing food", "avoiding records", "cleaning tools"]'::jsonb,0,'Records support accountability.','original'),
('127.407.d.5.B',4,'A signed, dated design notebook entry can later serve as:','["a game score", "evidence of when an idea was developed", "a school menu", "a weather map"]'::jsonb,1,'Dated entries establish a timeline.','original'),
('127.407.d.5.C',3,'A requirement that a filter must remove 90 percent of sediment is a:','["visual requirement only", "hobby", "functional requirement", "slogan"]'::jsonb,2,'Functional requirements say what a design must do.','original'),
('127.407.d.5.C',4,'A requirement that a rain barrel match the color of a school building is mainly a:','["budget item", "safety law", "chemical limit", "visual requirement"]'::jsonb,3,'Appearance requirements are visual.','original'),
('127.407.d.5.D',3,'Criteria for a stormwater basin design might include cost, safety, and:','["how well it holds water", "day of the week", "rainbow colors", "the designer''s age"]'::jsonb,0,'Criteria are measurable qualities of success.','original'),
('127.407.d.5.D',4,'Listing criteria before choosing among designs allows a team to:','["guess", "judge each option fairly", "skip testing", "avoid choosing"]'::jsonb,1,'Common criteria make comparison fair.','original'),
('127.407.d.5.E',3,'Sketching three different layouts for a wetland lets a team:','["skip planning", "avoid ideas", "compare ideas quickly", "hide data"]'::jsonb,2,'Sketches are fast ways to compare concepts.','original'),
('127.407.d.5.E',4,'A bar graph of pollutant levels at four creek sites is a visual tool that shows:','["the creek''s name", "the date of the sketch", "the cost of paper", "differences between sites"]'::jsonb,3,'Graphs reveal patterns.','original'),
('127.407.d.5.F',3,'To compare two filter designs fairly, a team should test both:','["under the same conditions", "without measuring", "on different days only", "once each at random"]'::jsonb,0,'Fair tests control conditions.','original'),
('127.407.d.5.F',4,'Measuring turbidity in NTU before and after each filter design produces:','["a rumor", "quantitative data", "opinions only", "a poem"]'::jsonb,1,'Numbers from measurements are quantitative.','original'),
('127.407.d.5.G',3,'Reducing flooding can be done with a retention pond, a green roof, or a larger pipe. This shows that problems often have:','["no solutions", "identical solutions", "multiple viable solutions", "one correct answer"]'::jsonb,2,'Several designs can meet one need.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_63_v1'
from (values
('127.407.d.5.G',4,'Because several designs may meet the same requirements, engineers choose among them using:','["the first idea", "coin flips", "volume of voices", "criteria and evidence"]'::jsonb,3,'Selection is based on data.','original'),
('127.407.d.6.A',3,'A decision matrix scores each design against weighted criteria. The design with the highest total is usually:','["the preferred option", "copied", "unrelated", "discarded"]'::jsonb,0,'Highest score is the best fit.','original'),
('127.407.d.6.A',4,'In a weighted decision matrix for choosing a water treatment method, a more important criterion gets a:','["random score", "higher weight", "lower weight", "zero score"]'::jsonb,1,'Weights reflect importance.','original'),
('127.407.d.6.B',3,'A risk matrix in a spreadsheet ranks threats by how likely they are and by their:','["author", "file size", "severity of impact", "color"]'::jsonb,2,'Risk combines likelihood and impact.','original'),
('127.407.d.6.B',4,'A threat that is very likely and would cause severe harm appears in which part of a risk matrix?','["the blank cells", "the title", "the low-risk zone", "the high-risk zone"]'::jsonb,3,'Likely, severe threats rank highest.','original'),
('127.407.d.6.C',3,'To study whether a creek is getting warmer, an engineer needs data on:','["water temperature over time", "school enrollment", "the price of cars", "sports scores"]'::jsonb,0,'Data must match the research question.','original'),
('127.407.d.6.C',4,'A research question about how fertilizer affects a lake should be matched with data on:','["song lyrics", "nutrient levels in the water", "movie ratings", "bus schedules"]'::jsonb,1,'Relevant data addresses the question.','original'),
('127.407.d.6.D',3,'A claim that a new filter works is based on a single test of one sample. A weakness in this evidence is its:','["bright color", "long name", "small sample size", "low price"]'::jsonb,2,'One sample is weak evidence.','original'),
('127.407.d.6.D',4,'An argument that a factory is not polluting uses data from a site 50 miles upstream. This evidence is limited because it is:','["too recent", "too numerical", "too accurate", "not from the relevant location"]'::jsonb,3,'Evidence must match the claim''s location.','original'),
('127.407.d.7.A',3,'A restoration site is described as 12 acres. An acre measures:','["area", "speed", "volume", "mass"]'::jsonb,0,'Acres are units of area.','original'),
('127.407.d.7.A',4,'Which unit is commonly used to measure the volume of water stored in a reservoir?','["degree Celsius", "acre-foot", "square mile", "mile per hour"]'::jsonb,1,'One acre-foot covers an acre one foot deep.','original'),
('127.407.d.7.B',3,'To estimate the area of an irregular wetland, a team can place a grid over a map and count the:','["bus stops", "trees named", "squares covered", "birds seen"]'::jsonb,2,'Grid counting estimates area.','original'),
('127.407.d.7.B',4,'Using aerial photographs to measure a stream''s length is an example of:','["taste testing", "guessing", "coin counting", "remote measurement"]'::jsonb,3,'Imagery measures large areas from a distance.','original'),
('127.407.d.7.C',3,'A tank holds 5,000 liters. How many cubic meters is that? (1 cubic meter = 1,000 liters)','["5 cubic meters", "0.5 cubic meters", "50 cubic meters", "500 cubic meters"]'::jsonb,0,'5,000 / 1,000 = 5.','original'),
('127.407.d.7.C',4,'A flow of 2 cubic feet per second equals how many cubic feet in one minute?','["60 cubic feet", "120 cubic feet", "12 cubic feet", "2 cubic feet"]'::jsonb,1,'2 x 60 = 120.','original'),
('127.407.d.7.D',3,'The best tool for measuring the depth of a stream at a given point is a:','["stopwatch", "bathroom scale", "calibrated depth rod", "thermometer"]'::jsonb,2,'Depth rods measure water depth.','original'),
('127.407.d.7.D',4,'Before using a pH meter on a water sample, a student should:','["freeze it", "paint it", "dry it with sand", "calibrate it with buffer solutions"]'::jsonb,3,'Calibration ensures accurate readings.','original'),
('127.407.d.8.A',3,'The Texas State Water Plan is updated every five years to meet the state''s future:','["water supply needs", "school lunches", "music needs", "road needs"]'::jsonb,0,'The plan projects future demand.','original'),
('127.407.d.8.A',4,'Regional planning groups help create the Texas State Water Plan by identifying:','["holiday dates", "strategies to meet future shortages", "new school mascots", "state flags"]'::jsonb,1,'Regions propose water strategies.','original'),
('127.407.d.8.B',3,'As a region''s population grows, the demand for water generally:','["stays at zero", "disappears", "increases", "freezes"]'::jsonb,2,'More people use more water.','original'),
('127.407.d.8.B',4,'A city adds 50,000 residents using 100 gallons per person per day. How much extra water per day is needed?','["50,000 gallons", "500,000 gallons", "50,000,000 gallons", "5,000,000 gallons"]'::jsonb,3,'50,000 x 100 = 5,000,000.','original'),
('127.407.d.8.C',3,'Drinking water contaminated with disease-causing bacteria can cause:','["waterborne illness", "faster growth", "stronger bones", "better sleep"]'::jsonb,0,'Pathogens in water make people sick.','original'),
('127.407.d.8.C',4,'Lead leaching from old pipes into drinking water is mainly a concern for:','["taste of ice", "long-term health effects", "sound levels", "water color only"]'::jsonb,1,'Lead builds up and harms health.','original'),
('127.407.d.8.D',3,'Two common sources of drinking water are surface water, such as reservoirs, and:','["rainbows", "road runoff only", "groundwater", "sea fog"]'::jsonb,2,'Aquifers supply groundwater.','original'),
('127.407.d.8.D',4,'Compared with surface water, groundwater from aquifers is usually:','["always saltier", "more exposed to sunlight", "stored in open air", "less affected by short-term runoff"]'::jsonb,3,'Soil filters and shields groundwater.','original'),
('127.407.d.8.E',3,'Potable water is water that is:','["safe to drink", "safe only for plants", "free of all minerals", "salt water"]'::jsonb,0,'Potable means drinkable.','original'),
('127.407.d.8.E',4,'One characteristic of potable water is that it has no harmful levels of:','["clear air", "pathogens and toxic chemicals", "sunlight", "oxygen"]'::jsonb,1,'Standards limit harmful substances.','original'),
('127.407.d.8.F',3,'Fertilizer and animal waste washed from fields into a stream are examples of contamination from:','["rainbows", "magnets", "runoff", "sunlight"]'::jsonb,2,'Runoff carries pollutants.','original'),
('127.407.d.8.F',4,'A leaking underground fuel tank near a well can contaminate drinking water through the:','["air vent", "window", "roof", "soil and groundwater"]'::jsonb,3,'Spilled fuel seeps down to aquifers.','original'),
('127.407.d.8.G',3,'Contaminant cycling describes how a pollutant moves through the air, water, soil, and:','["living organisms", "music", "coins", "calendars"]'::jsonb,0,'Pollutants circulate through ecosystems.','original'),
('127.407.d.8.G',4,'Mercury that settles in a lake, is eaten by small fish, and then by larger fish is an example of a pollutant:','["turning into gold", "moving up the food chain", "disappearing", "freezing"]'::jsonb,1,'Toxins accumulate along food chains.','original'),
('127.407.d.8.H',3,'A private well differs from a public drinking water system because its owner is responsible for:','["state-run treatment plants", "city water towers", "testing and maintaining it", "federal pipelines"]'::jsonb,2,'Private well owners handle upkeep.','original'),
('127.407.d.8.H',4,'In a public water system, water is stored in elevated tanks or towers mainly to maintain:','["temperature", "color", "taste", "pressure"]'::jsonb,3,'Height gives water pressure.','original'),
('127.407.d.9.A',3,'The federal law that sets standards for the quality of public drinking water is the:','["Safe Drinking Water Act", "Endangered Species Act", "Clean Air Act", "Homestead Act"]'::jsonb,0,'The SDWA protects public water supplies.','original'),
('127.407.d.9.A',4,'In Texas, the state agency that enforces drinking water standards is the:','["Texas Education Agency", "Texas Commission on Environmental Quality", "Texas Lottery Commission", "Texas Department of Transportation"]'::jsonb,1,'The TCEQ regulates public water systems.','original'),
('127.407.d.9.B',3,'A Consumer Confidence Report, mailed yearly by a water utility, tells customers about:','["tax rates", "the utility''s holiday party", "the quality of their drinking water", "local sports"]'::jsonb,2,'These reports share test results.','original'),
('127.407.d.9.B',4,'Water systems must compare measured contaminant levels with legal limits in annual:','["weather logs", "gossip columns", "sales flyers", "compliance reports"]'::jsonb,3,'Compliance reports show whether standards were met.','original'),
('127.407.d.9.C',3,'Which measurement is a chemical indicator of water quality?','["dissolved oxygen concentration", "pipe color", "bottle shape", "water''s popularity"]'::jsonb,0,'Chemical indicators are measured with tests or probes.','original'),
('127.407.d.9.C',4,'The presence of coliform bacteria in a sample is a biological indicator of possible:','["high altitude", "fecal contamination", "fresh paint", "sunny weather"]'::jsonb,1,'Coliforms signal waste contamination.','original'),
('127.407.d.9.D',3,'In a coliform culture assay, a water sample is placed on a growth medium and incubated to see if:','["the dish changes shape", "the sample freezes", "bacterial colonies grow", "salt forms"]'::jsonb,2,'Colonies show bacteria are present.','original'),
('127.407.d.9.D',4,'A coliform test is incubated at a controlled warm temperature because bacteria grow best when it is:','["boiling", "frozen solid", "dried out", "kept near body temperature"]'::jsonb,3,'Warmth speeds bacterial growth.','original'),
('127.407.d.9.E',3,'Turbidity is a measure of how:','["cloudy the water is", "deep the water is", "hot the water is", "salty the water is"]'::jsonb,0,'Suspended particles make water cloudy.','original'),
('127.407.d.9.E',4,'To collect a representative stream sample, a student should use a clean container and rinse it with:','["soap", "the water being sampled", "sand", "juice"]'::jsonb,1,'Rinsing avoids introducing other contaminants.','original'),
('127.407.d.9.F',3,'In a typical septic tank, solids settle to the bottom as sludge and grease floats as:','["ice", "foam glass", "scum", "steam"]'::jsonb,2,'Septic tanks separate solids, liquid, and scum.','original'),
('127.407.d.9.F',4,'In a modern municipal wastewater plant, large debris is removed first in which stage?','["final disinfection", "sludge drying", "effluent release", "preliminary screening"]'::jsonb,3,'Screens catch trash before other steps.','original'),
('127.407.d.9.G',3,'In wastewater treatment, bacteria help by:','["breaking down organic waste", "creating metals", "freezing water", "adding plastic"]'::jsonb,0,'Microbes digest organic matter.','original'),
('127.407.d.9.G',4,'Aeration basins add air to wastewater mainly to support:','["fish farming", "aerobic bacteria", "sunlight", "road salt"]'::jsonb,1,'Oxygen keeps helpful bacteria active.','original'),
('127.407.d.9.H',3,'Pharmaceutical residues and microplastics found in water supplies are often called:','["solid salts", "safe minerals", "emerging contaminants", "classic nutrients"]'::jsonb,2,'They are newly recognized pollutants.','original'),
('127.407.d.9.H',4,'Emerging contaminants are a challenge because treatment plants and regulations:','["ban all water", "always remove them", "are unnecessary", "may not yet address them"]'::jsonb,3,'Rules and technology lag behind discovery.','original'),
('127.407.d.9.I',3,'In activated sludge, protozoa and rotifers feed on:','["bacteria and small particles", "metal pipes", "sunlight", "salt crystals"]'::jsonb,0,'They are predators in the treatment ecosystem.','original'),
('127.407.d.9.I',4,'A healthy variety of protozoa and rotifers in a treatment basin indicates:','["freezing temperatures", "a well-functioning biological process", "a broken pipe", "a power failure"]'::jsonb,1,'Operators use them as health indicators.','original'),
('127.407.d.9.J',3,'Screening and settling are examples of which type of treatment process?','["biological", "nuclear", "physical", "chemical"]'::jsonb,2,'Physical processes separate materials by size or weight.','original'),
('127.407.d.9.J',4,'Adding chlorine to kill germs in drinking water is an example of a:','["biological process", "magnetic process", "physical process", "chemical process"]'::jsonb,3,'Disinfection uses chemicals.','original'),
('127.407.d.9.K',3,'Plants take up nitrates from contaminated water through their:','["roots", "fruit", "seeds only", "flowers"]'::jsonb,0,'Roots absorb dissolved nutrients.','original'),
('127.407.d.9.K',4,'Plants use the nitrogen from nitrates to build:','["glass", "proteins and tissue", "plastic", "rocks"]'::jsonb,1,'Nitrogen is a building block of plant proteins.','original')
